const int pinPIR   = 2;   // ИК-датчик движения
const int pinBuzzer= 8;   // Зумер
const int pinLED   = 13;  // Светодиод

void setup() {
  pinMode(pinPIR,   INPUT);
  pinMode(pinBuzzer, OUTPUT);
  pinMode(pinLED,  OUTPUT);
}

void loop() {
  int motion = digitalRead(pinPIR);  // читаем сигнал с датчика

  if (motion == HIGH) {              // если обнаружено движение
    digitalWrite(pinLED, HIGH);      // включаем светодиод
    tone(pinBuzzer, 2000);           // включаем звук (2000 Гц)
  } else {                           // если движения нет
    digitalWrite(pinLED, LOW);       // выключаем светодиод
    noTone(pinBuzzer);               // выключаем звук
  }
}
